{
  "root": "stack-wizard",
  "elements": [
    {
      "id": "stack-wizard",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "vertical"},
        {"key": "gap", "value": "lg"},
        {"key": "align", "value": "stretch"}
      ],
      "children": ["heading-title", "text-intro", "tabs-steps", "separator-nav", "stack-nav"]
    },
    {
      "id": "heading-title",
      "type": "Heading",
      "props": [
        {"key": "text", "value": "Welcome to Your Account Setup"},
        {"key": "level", "value": "h1"}
      ],
      "children": []
    },
    {
      "id": "text-intro",
      "type": "Text",
      "props": [
        {"key": "text", "value": "Let's get you started. This will only take a minute."},
        {"key": "variant", "value": "lead"}
      ],
      "children": []
    },
    {
      "id": "tabs-steps",
      "type": "Tabs",
      "props": [
        {"key": "tabs", "value": "[\"Account\", \"Preferences\", \"Done\"]"},
        {"key": "value", "value": "Account"}
      ],
      "children": ["panel-account", "panel-preferences", "panel-done"]
    },
    {
      "id": "panel-account",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "vertical"},
        {"key": "gap", "value": "md"}
      ],
      "children": ["input-name", "text-name-helper", "input-email", "text-email-helper", "input-password", "text-password-helper"]
    },
    {
      "id": "input-name",
      "type": "Input",
      "props": [
        {"key": "label", "value": "Full Name"},
        {"key": "placeholder", "value": "Jane Doe"}
      ],
      "children": []
    },
    {
      "id": "text-name-helper",
      "type": "Text",
      "props": [
        {"key": "text", "value": "Enter your full name as it appears on your ID."},
        {"key": "variant", "value": "muted"}
      ],
      "children": []
    },
    {
      "id": "input-email",
      "type": "Input",
      "props": [
        {"key": "label", "value": "Email"},
        {"key": "type", "value": "email"},
        {"key": "placeholder", "value": "jane@example.com"}
      ],
      "children": []
    },
    {
      "id": "text-email-helper",
      "type": "Text",
      "props": [
        {"key": "text", "value": "We'll send a verification link to this address."},
        {"key": "variant", "value": "muted"}
      ],
      "children": []
    },
    {
      "id": "input-password",
      "type": "Input",
      "props": [
        {"key": "label", "value": "Password"},
        {"key": "type", "value": "password"},
        {"key": "placeholder", "value": "••••••••"}
      ],
      "children": []
    },
    {
      "id": "text-password-helper",
      "type": "Text",
      "props": [
        {"key": "text", "value": "Must be at least 8 characters."},
        {"key": "variant", "value": "muted"}
      ],
      "children": []
    },
    {
      "id": "panel-preferences",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "vertical"},
        {"key": "gap", "value": "md"}
      ],
      "children": ["select-theme", "radio-notifications", "checkbox-newsletter"]
    },
    {
      "id": "select-theme",
      "type": "Select",
      "props": [
        {"key": "label", "value": "Theme"},
        {"key": "placeholder", "value": "Choose a theme"},
        {"key": "options", "value": "[\"Light\", \"Dark\", \"System\"]"},
        {"key": "value", "value": "Light"}
      ],
      "children": []
    },
    {
      "id": "radio-notifications",
      "type": "RadioGroup",
      "props": [
        {"key": "label", "value": "Notification frequency"},
        {"key": "options", "value": "[\"All updates\", \"Important only\", \"None\"]"},
        {"key": "value", "value": "All updates"}
      ],
      "children": []
    },
    {
      "id": "checkbox-newsletter",
      "type": "Checkbox",
      "props": [
        {"key": "label", "value": "Subscribe to our newsletter"},
        {"key": "checked", "value": "false"}
      ],
      "children": []
    },
    {
      "id": "panel-done",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "vertical"},
        {"key": "gap", "value": "md"}
      ],
      "children": ["alert-success", "stat-complete", "button-dashboard"]
    },
    {
      "id": "alert-success",
      "type": "Alert",
      "props": [
        {"key": "title", "value": "You're all set!"},
        {"key": "description", "value": "Your account has been created successfully."},
        {"key": "variant", "value": "default"}
      ],
      "children": []
    },
    {
      "id": "stat-complete",
      "type": "Stat",
      "props": [
        {"key": "label", "value": "Setup Progress"},
        {"key": "value", "value": "100%"},
        {"key": "change", "value": "Complete"},
        {"key": "trend", "value": "up"}
      ],
      "children": []
    },
    {
      "id": "button-dashboard",
      "type": "Button",
      "props": [
        {"key": "label", "value": "Go to Dashboard"},
        {"key": "variant", "value": "default"}
      ],
      "children": []
    },
    {
      "id": "separator-nav",
      "type": "Separator",
      "props": [],
      "children": []
    },
    {
      "id": "stack-nav",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "horizontal"},
        {"key": "gap", "value": "md"},
        {"key": "align", "value": "center"}
      ],
      "children": ["button-back", "button-next"]
    },
    {
      "id": "button-back",
      "type": "Button",
      "props": [
        {"key": "label", "value": "Back"},
        {"key": "variant", "value": "secondary"}
      ],
      "children": []
    },
    {
      "id": "button-next",
      "type": "Button",
      "props": [
        {"key": "label", "value": "Next"},
        {"key": "variant", "value": "default"}
      ],
      "children": []
    }
  ]
}
